import{_ as p,a0 as l,w as d,s as r,ao as o,I as t,a1 as e,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"BootISO：從 ISO 文件中創建一個可啓動的 USB 設備 | LCTT x X-CMD","titleTemplate":false,"description":"BootISO：從 ISO 文件中創建一個可啓動的 USB 設備 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BootISO：從 ISO 文件中創建一個可啓動的 USB 設備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BootISO：從 ISO 文件中創建一個可啓動的 USB 設備 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File","title":"BootISO：從 ISO 文件中創建一個可啓動的 USB 設備","tag":"201906","desc":""},"relativePath":"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File.md","filePath":"[post].md"}'),c={name:"201906/20180604 BootISO - A Simple Bash Script To Securely Create A Bootable USB Device From ISO File.md"};function h(u,s,b,g,S,m){const n=l("Link");return d(),r("div",null,[s[19]||(s[19]=o('<h1 id="bootiso-從-iso-文件中創建一個可啓動的-usb-設備" tabindex="-1">BootISO：從 ISO 文件中創建一個可啓動的 USB 設備 <a class="header-anchor" href="#bootiso-從-iso-文件中創建一個可啓動的-usb-設備" aria-label="Permalink to “BootISO：從 ISO 文件中創建一個可啓動的 USB 設備”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/16/110109qq0b7atyaped3ij2.jpg" alt=""></p><p>為了安裝操作系統，我們中的大多數人（包括我）經常從 ISO 文件中創建一個可啓動的 USB 設備。為達到這個目的，在 Linux 中有很多自由可用的應用程序。甚至在過去我們寫了幾篇介紹這種實用程序的文章。</p><p>每個人使用不同的應用程序，每個應用程序有它們自己的特色和功能。在這些應用程序中，一些應用程序屬於 CLI 程序，一些應用程序則是 GUI 的。</p><p>今天，我們將討論名為 BootISO 的實用程序類似工具。它是一個簡單的 bash 腳本，允許用户來從 ISO 文件中創建一個可啓動的 USB 設備。</p><p>很多 Linux 管理員使用 <code>dd</code> 命令開創建可啓動的 ISO ，它是一個著名的原生方法，但是與此同時，它也是一個非常危險的命令。因此，小心，當你用 <code>dd</code> 命令執行一些動作時。</p><p>建議閲讀：</p>',7)),t("ul",null,[t("li",null,[e(n,{href:"https://www.2daygeek.com/etcher-easy-way-to-create-a-bootable-usb-drive-sd-card-from-an-iso-image-on-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("Etcher：從一個 ISO 鏡像中創建一個可啓動的 USB 驅動器 & SD 卡的簡單方法",-1)])]),_:1})]),t("li",null,[e(n,{href:"https://www.2daygeek.com/create-a-bootable-usb-drive-from-an-iso-image-using-dd-command-on-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("在 Linux 上使用 dd 命令來從一個 ISO 鏡像中創建一個可啓動的 USB 驅動器",-1)])]),_:1})])]),s[20]||(s[20]=t("h3",{id:"bootiso-是什麼",tabindex:"-1"},[a("BootISO 是什麼 "),t("a",{class:"header-anchor",href:"#bootiso-是什麼","aria-label":"Permalink to “BootISO 是什麼”"},"​")],-1)),t("p",null,[e(n,{href:"https://github.com/jsamr/bootiso"},{default:i(()=>[...s[2]||(s[2]=[a("BootISO",-1)])]),_:1}),s[3]||(s[3]=a(" 是一個簡單的 bash 腳本，允許用户來安全的從一個 ISO 文件中創建一個可啓動的 USB 設備，它是用 bash 編寫的。",-1))]),s[21]||(s[21]=o(`<p>它不提供任何圖形用户界面而是提供了大量的選項，可以讓初學者順利地在 Linux 上來創建一個可啓動的 USB 設備。因為它是一個智能工具，能自動地選擇連接到系統上的 USB 設備。</p><p>當系統有多個 USB 設備連接，它將打印出列表。當你手動選擇了另一個硬盤而不是 USB 時，在這種情況下，它將安全地退出，而不會在硬盤上寫入任何東西。</p><p>這個腳本也將檢查依賴關係，並提示用户安裝，它可以與所有的軟件包管理器一起工作，例如 apt-get、yum、dnf、pacman 和 zypper。</p><h3 id="bootiso-的功能" tabindex="-1">BootISO 的功能 <a class="header-anchor" href="#bootiso-的功能" aria-label="Permalink to “BootISO 的功能”">​</a></h3><ul><li>它檢查選擇的 ISO 是否是正確的 mime 類型。如果不是，那麼退出。</li><li>如果你選擇除 USB 設備以外的任何其它的磁盤（本地硬盤），BootISO 將自動地退出。</li><li>當你有多個驅動器時，BootISO 允許用户選擇想要使用的 USB 驅動器。</li><li>在擦除和分區 USB 設備前，BootISO 會提示用户確認。</li><li>BootISO 將正確地處理來自一個命令的任何錯誤，並退出。</li><li>BootISO 在遇到問題退出時將調用一個清理例行程序。</li></ul><h3 id="如何在-linux-中安裝-bootiso" tabindex="-1">如何在 Linux 中安裝 BootISO <a class="header-anchor" href="#如何在-linux-中安裝-bootiso" aria-label="Permalink to “如何在 Linux 中安裝 BootISO”">​</a></h3><p>在 Linux 中安裝 BootISO 有幾個可用的方法，但是，我建議用户使用下面的方法安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://git.io/bootiso -O</span></span>
<span class="line"><span>$ chmod +x bootiso</span></span>
<span class="line"><span>$ sudo mv bootiso /usr/local/bin/</span></span></code></pre></div><p>一旦 BootISO 已經安裝，運行下面的命令來列出可用的 USB 設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE   TYPE</span></span>
<span class="line"><span>sdd  1       32G  running disk</span></span></code></pre></div><p>如果你僅有一個 USB 設備，那麼簡單地運行下面的命令來從一個 ISO 文件中創建一個可啓動的 USB 設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso /path/to/iso file</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span>
<span class="line"><span>Granting root privileges for bootiso.</span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE   TYPE</span></span>
<span class="line"><span>sdd  1       32G  running disk</span></span>
<span class="line"><span>Autoselecting \`sdd&#39; (only USB device candidate)</span></span>
<span class="line"><span>The selected device \`/dev/sdd&#39; is connected through USB.</span></span>
<span class="line"><span>Created ISO mount point at \`/tmp/iso.vXo&#39;</span></span>
<span class="line"><span>\`bootiso&#39; is about to wipe out the content of device \`/dev/sdd&#39;.</span></span>
<span class="line"><span>Are you sure you want to proceed? (y/n)&gt;y</span></span>
<span class="line"><span>Erasing contents of /dev/sdd...</span></span>
<span class="line"><span>Creating FAT32 partition on \`/dev/sdd1&#39;...</span></span>
<span class="line"><span>Created USB device mount point at \`/tmp/usb.0j5&#39;</span></span>
<span class="line"><span>Copying files from ISO to USB device with \`rsync&#39; </span></span>
<span class="line"><span>Synchronizing writes on device \`/dev/sdd&#39; </span></span>
<span class="line"><span>\`bootiso&#39; took 250 seconds to write ISO to USB device with \`rsync&#39; method.</span></span>
<span class="line"><span>ISO succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully ejected.</span></span>
<span class="line"><span>You can safely remove it !</span></span></code></pre></div><p>當你有多個 USB 設備時，可以使用 <code>--device</code> 選項指明你的設備名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>默認情況下，BootISO 使用 <code>rsync</code> 命令來執行所有的動作，如果你想使用 <code>dd</code> 命令代替它，使用下面的格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --dd -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>如果你想跳過 mime 類型檢查，BootISO 實用程序帶有下面的選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --no-mime-check -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>為 BootISO 添加下面的選項來跳過在擦除和分區 USB 設備前的用户確認。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -d /dev/sde /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>連同 <code>-y</code> 選項一起，啓用自動選擇 USB 設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -a /opt/iso_images/archlinux-2018.05.01-x86_64.iso</span></span></code></pre></div><p>為知道更多的 BootISO 選項，運行下面的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -h</span></span>
<span class="line"><span>Create a bootable USB from any ISO securely.</span></span>
<span class="line"><span>Usage: bootiso [...] </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-h, --help, help             Display this help message and exit.</span></span>
<span class="line"><span>-v, --version                Display version and exit.</span></span>
<span class="line"><span>-d, --device         Select  block file as USB device.</span></span>
<span class="line"><span>                             If  is not connected through USB, \`bootiso&#39; will fail and exit.</span></span>
<span class="line"><span>                             Device block files are usually situated in /dev/sXX or /dev/hXX.</span></span>
<span class="line"><span>                             You will be prompted to select a device if you don&#39;t use this option.</span></span>
<span class="line"><span>-b, --bootloader             Install a bootloader with syslinux (safe mode) for non-hybrid ISOs. Does not work with \`--dd&#39; option.</span></span>
<span class="line"><span>-y, --assume-yes             \`bootiso&#39; won&#39;t prompt the user for confirmation before erasing and partitioning USB device.</span></span>
<span class="line"><span>                             Use at your own risks.</span></span>
<span class="line"><span>-a, --autoselect             Enable autoselecting USB devices in conjunction with -y option.</span></span>
<span class="line"><span>                             Autoselect will automatically select a USB drive device if there is exactly one connected to the system.</span></span>
<span class="line"><span>                             Enabled by default when neither -d nor --no-usb-check options are given.</span></span>
<span class="line"><span>-J, --no-eject               Do not eject device after unmounting.</span></span>
<span class="line"><span>-l, --list-usb-drives        List available USB drives.</span></span>
<span class="line"><span>-M, --no-mime-check          \`bootiso&#39; won&#39;t assert that selected ISO file has the right mime-type.</span></span>
<span class="line"><span>-s, --strict-mime-check      Disallow loose application/octet-stream mime type in ISO file.</span></span>
<span class="line"><span>--                           POSIX end of options.</span></span>
<span class="line"><span>--dd                         Use \`dd&#39; utility instead of mounting + \`rsync&#39;.</span></span>
<span class="line"><span>                             Does not allow bootloader installation with syslinux.</span></span>
<span class="line"><span>--no-usb-check               \`bootiso&#39; won&#39;t assert that selected device is a USB (connected through USB bus).</span></span>
<span class="line"><span>                             Use at your own risks.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Readme</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Bootiso v2.5.2.</span></span>
<span class="line"><span>    Author: Jules Samuel Randolph</span></span>
<span class="line"><span>    Bugs and new features: https://github.com/jsamr/bootiso/issues</span></span>
<span class="line"><span>    If you like bootiso, please help the community by making it visible:</span></span>
<span class="line"><span>    * star the project at https://github.com/jsamr/bootiso</span></span>
<span class="line"><span>    * upvote those SE post: https://goo.gl/BNRmvm https://goo.gl/YDBvFe</span></span></code></pre></div><hr>`,26)),t("p",null,[s[5]||(s[5]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/bootiso-a-simple-bash-script-to-securely-create-a-bootable-usb-device-in-linux-from-iso-file/"},{default:i(()=>[...s[4]||(s[4]=[a("https://www.2daygeek.com/bootiso-a-simple-bash-script-to-securely-create-a-bootable-usb-device-in-linux-from-iso-file/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:i(()=>[...s[6]||(s[6]=[a("Prakash Subramanian",-1)])]),_:1}),s[11]||(s[11]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),e(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[8]||(s[8]=[a("robsean",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const B=p(c,[["render",h]]);export{y as __pageData,B as default};
